/**
 * Postgres 中心 schema（幂等）。
 *
 * 取代原 better-sqlite3 的 CREATE/ALTER 内联 DDL：
 * - INTEGER PK AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
 * - REAL → DOUBLE PRECISION（金额/比率；避免 NUMERIC 的字符串返回问题）
 * - DATETIME/CURRENT_TIMESTAMP → TIMESTAMPTZ now()（驱动层统一转 ISO 字符串）
 * - 毫秒时间戳列（sessions/oauth_states.expires_at）保持 BIGINT
 *
 * 框架自建表（task_locks / mutex_locks / sync_events / data_cache /
 * retry_tasks）一并纳入中心 schema，使类构造函数无需再执行 DDL。
 */
export const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  password TEXT NOT NULL,
  email TEXT,
  role TEXT NOT NULL DEFAULT 'viewer',
  subscription_plan TEXT,
  subscription_stores BIGINT,
  subscription_ai_calls BIGINT,
  subscription_features TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS subscription_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  old_plan TEXT,
  new_plan TEXT,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS shops (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  shop_name TEXT NOT NULL,
  domain TEXT NOT NULL,
  access_token TEXT NOT NULL,
  scope TEXT DEFAULT '',
  status TEXT DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shop_id BIGINT NOT NULL,
  name TEXT NOT NULL,
  category TEXT,
  price DOUBLE PRECISION,
  cost DOUBLE PRECISION,
  sales BIGINT DEFAULT 0,
  stock BIGINT DEFAULT 0,
  status TEXT DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(shop_id) REFERENCES shops(id)
);

CREATE TABLE IF NOT EXISTS orders (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shop_id BIGINT NOT NULL,
  order_number TEXT UNIQUE,
  customer_name TEXT,
  total_amount DOUBLE PRECISION,
  status TEXT DEFAULT 'pending',
  shipping_region TEXT,
  shipping_weight DOUBLE PRECISION,
  logistics_channel TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(shop_id) REFERENCES shops(id)
);

CREATE TABLE IF NOT EXISTS order_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id BIGINT NOT NULL,
  product_id BIGINT,
  name TEXT NOT NULL,
  quantity BIGINT NOT NULL DEFAULT 1,
  unit_price DOUBLE PRECISION,
  subtotal DOUBLE PRECISION,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(order_id) REFERENCES orders(id)
);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);

CREATE TABLE IF NOT EXISTS tracking_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id BIGINT NOT NULL,
  status TEXT NOT NULL,
  location TEXT,
  description TEXT,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(order_id) REFERENCES orders(id)
);
CREATE INDEX IF NOT EXISTS idx_tracking_events_order ON tracking_events(order_id, occurred_at DESC);

-- P3-02 聚合索引：订单按店/状态/时间维度的聚合查询（1000 单样本 <200ms）。
CREATE INDEX IF NOT EXISTS idx_orders_shop_status ON orders(shop_id, status);
CREATE INDEX IF NOT EXISTS idx_orders_shop_created ON orders(shop_id, created_at DESC);

CREATE TABLE IF NOT EXISTS task_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_type TEXT NOT NULL,
  task_name TEXT NOT NULL,
  status TEXT DEFAULT 'pending',
  input TEXT,
  output TEXT,
  error TEXT,
  user_id BIGINT,
  root_task_id BIGINT,
  parent_task_id BIGINT,
  attempt_number BIGINT NOT NULL DEFAULT 1,
  started_at TIMESTAMPTZ,
  ended_at TIMESTAMPTZ,
  chain BIGINT NOT NULL DEFAULT 0,
  idempotency_key TEXT,
  claimed_by TEXT,
  heartbeat_at TIMESTAMPTZ,
  lease_until TIMESTAMPTZ,
  requeue_count BIGINT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_task_root ON task_logs(root_task_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_task_idempotency ON task_logs(idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_task_queue_pending ON task_logs(created_at) WHERE status = 'pending';

CREATE TABLE IF NOT EXISTS task_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id BIGINT NOT NULL,
  from_status TEXT,
  to_status TEXT NOT NULL,
  agent_type TEXT NOT NULL,
  attempt_number BIGINT NOT NULL DEFAULT 1,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_task_events_task ON task_events(task_id, id);

-- 任务状态事件触发器（替代 SQLite 版迁移）。
CREATE OR REPLACE FUNCTION task_created_event_fn() RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO task_events(task_id, from_status, to_status, agent_type, attempt_number, error)
  VALUES (NEW.id, NULL, NEW.status, NEW.agent_type, NEW.attempt_number, NEW.error);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS task_created_event ON task_logs;
CREATE TRIGGER task_created_event
  AFTER INSERT ON task_logs
  FOR EACH ROW EXECUTE FUNCTION task_created_event_fn();

CREATE OR REPLACE FUNCTION task_status_event_fn() RETURNS TRIGGER AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO task_events(task_id, from_status, to_status, agent_type, attempt_number, error)
    VALUES (NEW.id, OLD.status, NEW.status, NEW.agent_type, NEW.attempt_number, NEW.error);
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS task_status_event ON task_logs;
CREATE TRIGGER task_status_event
  AFTER UPDATE ON task_logs
  FOR EACH ROW EXECUTE FUNCTION task_status_event_fn();

CREATE TABLE IF NOT EXISTS knowledge_base (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_type TEXT NOT NULL,
  question TEXT NOT NULL,
  answer TEXT NOT NULL,
  language TEXT DEFAULT 'zh',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS shared_context (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_type TEXT NOT NULL,
  key TEXT NOT NULL,
  value TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_shared_context_agent_key ON shared_context(agent_type, key);

CREATE TABLE IF NOT EXISTS agent_progress (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_type TEXT NOT NULL,
  task_id TEXT NOT NULL,
  steps TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_progress_task ON agent_progress(agent_type, task_id);

CREATE TABLE IF NOT EXISTS user_preferences (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  locale TEXT DEFAULT 'zh',
  timezone TEXT DEFAULT 'Asia/Shanghai',
  currency TEXT DEFAULT 'CNY',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS oauth_states (
  state TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  expires_at BIGINT NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_oauth_states_state ON oauth_states(state);

CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  expires_at BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);

CREATE TABLE IF NOT EXISTS compliance_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  kind TEXT NOT NULL,
  payload TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_compliance_user_kind ON compliance_items(user_id, kind);

CREATE TABLE IF NOT EXISTS ad_campaigns (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  external_id TEXT NOT NULL,
  name TEXT NOT NULL,
  platform TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  budget DOUBLE PRECISION DEFAULT 0,
  spent DOUBLE PRECISION DEFAULT 0,
  roas DOUBLE PRECISION DEFAULT 0,
  clicks BIGINT DEFAULT 0,
  conversions BIGINT DEFAULT 0,
  ctr DOUBLE PRECISION DEFAULT 0,
  audience_json TEXT,
  creatives_json TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(user_id, external_id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_user ON ad_campaigns(user_id);

CREATE TABLE IF NOT EXISTS ad_suggestions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  campaign_external_id TEXT,
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  expected_impact TEXT,
  action TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(user_id, campaign_external_id, title),
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_ad_suggestions_user ON ad_suggestions(user_id);

-- 框架运行时表：任务锁（唯一 resource，靠唯一约束实现互斥获取）。
CREATE TABLE IF NOT EXISTS task_locks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  resource TEXT UNIQUE NOT NULL,
  agent_type TEXT NOT NULL,
  task_id TEXT NOT NULL,
  acquired_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS mutex_locks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  resource TEXT UNIQUE NOT NULL,
  holder TEXT NOT NULL,
  acquired_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sync_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source TEXT NOT NULL,
  agent_type TEXT NOT NULL,
  key TEXT NOT NULL,
  action TEXT NOT NULL,
  timestamp TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_sync_events_source ON sync_events(source);

CREATE TABLE IF NOT EXISTS data_cache (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source TEXT NOT NULL,
  key TEXT NOT NULL,
  data TEXT NOT NULL,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  UNIQUE(source, key)
);

CREATE TABLE IF NOT EXISTS retry_tasks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_type TEXT NOT NULL,
  task_name TEXT NOT NULL,
  input TEXT NOT NULL,
  retry_count BIGINT DEFAULT 0,
  max_retries BIGINT NOT NULL,
  next_retry_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- P5-02 产品埋点与归因（signup / shop_connected / task_submitted / task_completed）
CREATE TABLE IF NOT EXISTS analytics_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  event_name TEXT NOT NULL,
  properties_json TEXT,
  source TEXT,
  session_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_analytics_events_user
  ON analytics_events(user_id, event_name, created_at);
`;

/**
 * 已存在 PG 库的增量迁移（幂等）：
 * task_logs 补充生命周期列；存量 task_logs 行回填 task_events；
 * P2 订阅列/配额表；P3 订单明细/物流轨迹表与聚合索引。
 */
export const LIFECYCLE_MIGRATION_SQL = `
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS root_task_id BIGINT;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS parent_task_id BIGINT;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS attempt_number BIGINT NOT NULL DEFAULT 1;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS ended_at TIMESTAMPTZ;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS chain BIGINT NOT NULL DEFAULT 0;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS claimed_by TEXT;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS lease_until TIMESTAMPTZ;
ALTER TABLE task_logs ADD COLUMN IF NOT EXISTS requeue_count BIGINT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_plan TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_stores BIGINT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_ai_calls BIGINT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_features TEXT;
CREATE TABLE IF NOT EXISTS subscription_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  old_plan TEXT,
  new_plan TEXT,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_task_idempotency ON task_logs(idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_task_queue_pending ON task_logs(created_at) WHERE status = 'pending';

CREATE TABLE IF NOT EXISTS order_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id BIGINT NOT NULL,
  product_id BIGINT,
  name TEXT NOT NULL,
  quantity BIGINT NOT NULL DEFAULT 1,
  unit_price DOUBLE PRECISION,
  subtotal DOUBLE PRECISION,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE TABLE IF NOT EXISTS tracking_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id BIGINT NOT NULL,
  status TEXT NOT NULL,
  location TEXT,
  description TEXT,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_tracking_events_order ON tracking_events(order_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_shop_status ON orders(shop_id, status);
CREATE INDEX IF NOT EXISTS idx_orders_shop_created ON orders(shop_id, created_at DESC);

CREATE TABLE IF NOT EXISTS analytics_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  event_name TEXT NOT NULL,
  properties_json TEXT,
  source TEXT,
  session_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_analytics_events_user
  ON analytics_events(user_id, event_name, created_at);

INSERT INTO task_events(task_id, from_status, to_status, agent_type, attempt_number, error)
  SELECT id, NULL, status, agent_type, attempt_number, error FROM task_logs t
  WHERE NOT EXISTS (SELECT 1 FROM task_events e WHERE e.task_id = t.id);
`;
